INSERT INTO `web_content` (`content_id`, `channel_id`, `content_cat_id`, `title`, `title_eng`, `description`, `description_eng`, `file`, `file_eng`, `posted`, `updated`, `status`, `published`, `type`, `param1`, `param2`, `param3`, `ispromo`) VALUES
(171, 42, 0, 'General Purpose', '', '<p>We offers a wide range of general purpose media to support microbiological testing in laboratories around the world. This range includes media for sample preparation and dilution, microorganism maintenance, quality control testing, diagnostic confirmation media.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Culture media &amp; reagent for Food analysis</p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 3719px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 29px;\">\r\n<td style=\"width: 12.7345%; height: 29px; text-align: center;\"><strong>Catalogue</strong></td>\r\n<td style=\"width: 29.8603%; height: 29px; text-align: center;\"><strong>Product&nbsp;</strong></td>\r\n<td style=\"width: 57.4051%; height: 29px; text-align: center;\"><strong>Application</strong></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">74156</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">A.F. Genital System</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for detection, count and susceptibility test of pathogenic urogenital microorganisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">71670</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Copro System</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for direct microbial identification of intestinal pathogenic microorganisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">71675</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Copro System Plus</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for detection and presumptive identification of intestinal pathogenic microorganisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">72592</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Mycoplasma System Plus</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the detection, semi-quantitative determination and susceptibility test of urogenital mycoplasmas.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">72593</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Mycoplasma System VET</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for count, identification and susceptibility testing of mycoplasmas in the veterinary field.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">71679</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Pathogenic System</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the identification of pathogenic microorganisms from pharyngeal, cutaneous, auricular and ophthalmic swabs, expectorate and other clinical specimens.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">71681</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Pathogenic System AST</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the identification and susceptibility testing of the main pathogenic microorganisms directly from several clinical specimens.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">74161</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Urin System Chrom</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for microbial count, identification and susceptibility testing, directly from urine specimens.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; height: 18px; text-align: center;\">74160</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Urin System Plus</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for microbial count, identification and susceptibility testing directly from urine specimens.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">71714</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">Integral System ENTEROBACTERIA</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Colorimetric system for biochemical identification and susceptibility testing of enterobacteria</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71724</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Integral System GARDNERELLA</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Colorimetric system for identification and susceptibility testing of <em>Gardnerella vaginalis.</em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71718</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Integral System STAPHYLOCOCCI</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Colorimetric system for biochemical identification and susceptibility testing of staphylococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71822</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Integral System YEASTS Plus</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for identification of most clinically important yeasts and sensitivity evaluation to antimycotics.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">76031</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SensiQuattro Gram-negative EU</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for determination of the Minimum Inhibitory Concentration (MIC) of gram-negative bacteria with the broth microdilution method.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">76032</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SensiQuattro Gram-positive EU</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for determination of the Minimum Inhibitory Concentration (MIC) of gram-positive bacteria with the broth microdilution method.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">76033</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SensiQuattro Candida EU</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Panel for determining the susceptibility testing of <em>Candida spp.</em> with antimycotic agents.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">76010</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SensiTest Gram-negative</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the susceptibility testing of gram-negative bacteria and enterococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">76020</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SensiTest Gram-positive</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the susceptibility testing of gram-negative bacteria and enterococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">78619</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">EnteroPluri-Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Identification system of Enterobacteriaceae and other gram negative, oxidase negative bacteria.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">78621</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Oxi/Ferm Pluri Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the identification of Gram negative, oxidase positive bacteria.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71620</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Anaerobe System</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the identification of anaerobic microorganisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71618</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Entero System 18 R</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the identification of Gram-negative, oxidase negative enterobacteria.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71619</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Entero System 24R</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the identification of Gram-negative, oxidase negative enterobacteria.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71640</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Listeria System 18 R</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for biochemical identification of <em>Listeria spp. </em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71630</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Staf System 18 R</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the identification of <em>Staphylococcus spp. </em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\" width=\"64\">72560</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Strepto System 12R</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for the identification of Streptococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID-62CE</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; STREP-ID</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">For the identification of Streptococci and Enterococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID-64CE</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; GN-ID A</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">For the identification of aerobic and facultative anaerobic gram negative bacteria (Enterobacteriaceae and miscellaneous gram negative bacteria).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID-65CE</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; GN-ID B&nbsp;</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">For use as an additional 12 test system for the identification of Miscellaneous Gram negative and oxidase positive bacteria.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID-67</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Listeria-ID</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">For the identification of Listeria species.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID-66CE</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Bacillus ID</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">For the identification of mesophilic Bacillus species isolated from food materials and the environment. (Not available for clinical use within the EU).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID-69CE</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Staph ID</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">For the identification of Staphylococci from clinical and veterinary samples.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">RAP01&nbsp;</td>\r\n<td style=\"width: 29.8603%;\">Microgen&reg; Rap-ID L. mono&trade;</td>\r\n<td style=\"width: 57.4051%;\">Rapid Confirmation of <em>L. monocytogenes</em> isolated on chromogenic agar plate media.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61A</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Nitrate Reagent A</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61B</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Nitrate Reagent B</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61C</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Voges-Proskauer I Reagent</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61D</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Voges-Proskauer II Reagent</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61E</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; TDA Reagent</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61F</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Indole Kovacs Reagent</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61G</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Oxidase Strips</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Strips containing reagent for use in oxidase test.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61H</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Mineral Oil</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID61K</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; PYR Reagent</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">MID-61L</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Ninhydrin Reagent</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the identification system.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80405</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Mc Farland STANDARD SET 0.5 - 1.0 - 2.0 - 3.0 - 4.0</td>\r\n<td style=\"width: 57.4051%; height: 108px;\" rowspan=\"6\">McFarland standards are used as turbidity standards in the preparation of suspensions of microorganisms and has particular application in the preparation of bacterial inocula for performing antimicrobial susceptibility testing</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80400</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">McFarland 0.5 Barium Sulphate Standard</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80401</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">McFarland 1 Barium Sulphate Standard</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80402</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">McFarland 2 Barium Sulphate Standard</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80403</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">McFarland 3 Barium Sulphate Standard</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80404</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">McFarland 4 Barium Sulphate Standard</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88008</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Aesculin Bile Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test to identify Group D streptococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88016</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Arginine Decarboxylase Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test to evidence arginine decarboxylation to be used for enterobacteria identification.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">9502</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Bacitracin Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Bacitracin Test are paper discs impregnated with 0.04 units of Bacitracin that are used to distinguish Group A <em>Lancefield streptococci</em> from other beta haemolytic streptococci belonging to different Groups.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88033</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Beta Lactamase Sticks</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test in strip for detecting the enzyme beta-lactamase which confers resistance to pencicillins and cephalosporins in a wide variety of both Gram positive and Gram negative microorganisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88041</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Brilliant Green 100 &mu;g</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Test for differentiating common anaerobic bacteria.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88027</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">CAMP Test &ndash; R</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test for identification of <em>Listeria spp.</em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88021</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">CAMP Test &ndash; S</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test for identification of <em>Listeria spp. </em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">87003</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Catalase Reagent</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for rapid detection of catalase enzyme, in dropper bottles.</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 54px;\">88023</td>\r\n<td style=\"width: 29.8603%; height: 54px;\">Catalase / Oxy Test</td>\r\n<td style=\"width: 57.4051%; height: 54px;\">Rapid test for the detection of catalase and peroxidase enzymes used in microbiology for the differentiation and identification of bacterial strains.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">80057</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">H2O2 Reagent</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Reagent for microbiological use made of a H2O2 solution, for the performance of the catalase test.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">88042</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">Citrate Test</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">For the identification of Enterobacteriaceae and non-fermenting gram-negative bacteria.</td>\r\n</tr>\r\n<tr style=\"height: 72px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 72px;\">88030</td>\r\n<td style=\"width: 29.8603%; height: 72px;\">Coagulase Test</td>\r\n<td style=\"width: 57.4051%; height: 72px;\">COAGULASE TEST is constituted by lyophilic rabbit plasma<br />containing EDTA (Ethylenediaminetetraacetic Acid) used for the detection of coagulase enzyme produced by <em>Staphylococcus aureus.</em></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">88040</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">C-390</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Discs containing antibiotic C-390 for the identification of <em>Pseudomonas aeruginosa.</em></td>\r\n</tr>\r\n<tr style=\"height: 72px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 72px;\">88006</td>\r\n<td style=\"width: 29.8603%; height: 72px;\">E. coli Test</td>\r\n<td style=\"width: 57.4051%; height: 72px;\">Rapid test for <em>Escherichia coli</em> identification. The test emphasizes three important biochemical reactions to differentiate <em>E. coli</em> from other enterobacteria; reactions are ONPG, fluorescence and indole production.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88031</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Gram Test Stick</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">GRAM TEST STICK is a rapid test for differentiation of Gram negative from Gram-positive micro-organisms. The sticks are impregnated with the reagent L-alanine-4-nitroanilide which, on<br />contact with colonies of Gram-negative bacterial colonies, reacts<br />by changing colour to blue-violet following addition of the<br />detector reagent (Gram Test Reagent).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88013</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">H2S Rapid Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test for hydrogen sulfide (H2S) production.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88007</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Hippurate Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test tube for the detection of hippurate hydrolysis.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88032</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Indole Test Stick</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test on stick for determination of tryptophanase enzyme.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88010</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Listeria-mono Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Enzymatic test on tube for <em>Listeria monocytogenes</em> identification.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88014</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Lysine Decarboxylase Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test to evidence lysine decarboxylation.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">9508</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Metronidazole Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test for Metronidazole Test&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80273</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Ninhydrin 7%</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for Hippurate Test.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88009</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Nitrate Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test to detect the reduction from nitrate to nitrite by bacteria.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88043</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">O129 discs 150 &mu;g</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">O129 DISC is a test used for differentiation of <em>Vibrio spp.</em> based on sensitivity to vibrio-static agent O129 (2,4-diamino-6,7-di-isopropyl-pteridine phosphate)</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88044</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">O129 discs 10 &mu;g</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">O129 DISC is a test used for differentiation of Vibrio spp based on sensitivity to vibrio-static agent O129 (2,4-diamino-6,7-di-isopropyl-pteridine phosphate).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88105</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ONPG Discs</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test for the detection of bacterial &beta;-galattosidase.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88005</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ONPG Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test for the detection of bacterial &beta;-galattosidase.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">9501</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Optochine Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Optochine Test is constituted by paper discs, each one containing 5 &micro;g of Optochin (Ethylhydrocupreine hydrochloride), used for differentiating <em>Streptococcus pneumoniae</em> from the other alpha-haemolytic streptococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88015</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Ornithine Decarboxylase Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test to evidence ornithine decarboxylation</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">87005</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Oxidase Reagent</td>\r\n<td style=\"width: 57.4051%; height: 72px;\" rowspan=\"4\">Rapid test for detection of cytochrome oxidase enzymatic activity.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88004</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Oxidase Test Discs</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88029</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Oxidase Test Sticks</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88003</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Oxidase Test Swabs</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88034</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Peptidase A Sticks</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test in strip for the identification of group A and group D streptococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">87004</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Phenylalanine Reagent</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the phenylalanine deamination test, in dropper bottles.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88020</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">S.F. Rapid Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test for the determination of group D streptococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">9511</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Sulphonamide</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Reagent for the Sulphonamide test.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88024</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Urea / Indole Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test for detection of urease and indole production.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">88011</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Urea Rapid Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid test to evidence urease production.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">9504</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">V Factor Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">X FACTOR TEST, V FACTOR TEST and V+X FACTOR TEST are constituted by paper discs with special features, containing the respective coagulation factors, used for differentiating <em>Haemophilus spp. </em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">9503</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">X Factor Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">X FACTOR TEST, V FACTOR TEST and V+X FACTOR TEST are constituted by paper discs with special features, containing the respective coagulation factors, used for differentiating <em>Haemophilus spp.</em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">9505</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">X + V Factor Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">X FACTOR TEST, V FACTOR TEST and V+X FACTOR TEST are constituted by paper discs with special features, containing the respective coagulation factors, used for differentiating <em>Haemophilus spp.</em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80294</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ALBERT Color KIT</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">kit for staining diphtheria corynebacteria present in clinical samples or culture media</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80299</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Crystal Violet Solution (Gram staining)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">CRYSTAL VIOLET SOLUTION is a solution utilized for Gram staining.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80295</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">DECOLOURIZING Solution (Gram staining)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Decolourizing solution for Gram staining.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80293</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">GRAM Color KIT</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">GRAM COLOR KIT is a kit for staining micro-organisms that allows them to be differentiated into two categories: Gram-positives (Gram+), which are coloured blue, and Gram-negatives (Gram-), which are coloured red. Combined with direct observation of the cell morphology, this staining constitutes the first level in the taxonomic classification of prokaryotes.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80380</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">KINYOUN Color KIT</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">KINYOUN COLOR KIT (Tan-Thiam-Hok and Devulder method) is a kit for colouring alcohol3acid resistant bacteria in clinical samples or culture media.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80296</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">LUGOL PVP Solution (Gram staining)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Lugol solution to utilized for Gram staining.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80277</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">METHYLENE BLUE</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">0.3% Methylene Blue solution for Ziehl-Neelsen coloration.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80275</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">MIF Color KIT</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Colouring and fixative solution for eggs and fecal parasite.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80290</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SAFRANINE Solution (Gram staining)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Solution to use for Gram staining</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80276</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ZIEHL &ndash; NEELSEN Color KIT</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Kit for colouring acid-alcohol resistant bacteria present in pathological samples or in culture media.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500152</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest (MacConkey Agar / Cetrimide Agar / Cled Andrade Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500232</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest N (MacConkey Agar / Cetrimide Agar / Cled Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500242</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest C (MacConkey MUG Agar / Cetrimide Agar / Cled Andrade Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500412</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest EC (MacConkey Agar / E.coli Agar / Cled Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500302</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest 2 (Cled Agar/ MacConkey Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500182</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest M (MacConkey Agar / Malt Selective Agar / Cled Andrade Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500402</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest MaltO (MacConkey Agar / Malt Agar / Cled Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500702</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest EF (MacConkey Agar / Bile Aesculin Agar / Cled Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">500142</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Uritest PENTA (Cled Agar / MacConkey Agar / Cetrimide Agar / Malt Agar / Bile Aesculin Agar)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urinary Infections.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">50020</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">VAGITEST (Chocolate / Rogosa / Thayer Martin)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Urogenital Infections</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">50021</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">DERMATEST (Malto / CORN MEAL / DTM-TAPLIN)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Dip-Slide for the screening of Dermatological Infections</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">525262</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contact Slide 1 (PCA + TTC + NEUTRALIZING / V.R.B.G. AGAR + NEUTRALIZING)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Total bacterial count, enterobacteria, with inactivation of disinfectants.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">525272</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contact Slide 2 (PCA + TTC + NEUTRALIZING / ROSE BENGAL CAF AGAR + NEUTRALIZING)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Total bacterial count, yeasts and moulds, with inactivation of disinfectants.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">525302</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contact Slide 3 (PCA+TTC + NEUTRALIZING / VOGEL JOHNSON AGAR)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Total bacterial count with inactivation of disinfectants, staphylococci.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">525282</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contact Slide 4 (CETRIMIDE AGAR + NEUTRALIZING / ROSE BENGAL CAF AGAR + NEUTRALIZING)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\"><em>Peudomonas spp</em>., yeasts and moulds.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">525312</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contact Slide 5 (V.R.B.G. AGAR + NEUTRALIZING / BILE ESCULIN AGAR + NEUTRALIZING)</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Enterobacteria, fecal streptococci, with inactivation of disinfectants.</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 54px;\">525622</td>\r\n<td style=\"width: 29.8603%; height: 54px;\">Contact Slide 8 (PCA + TTC + NEUTRALIZING / V.R.B.L. AGAR + NEUTRALIZING)</td>\r\n<td style=\"width: 57.4051%; height: 54px;\">Total bacterial count, coliforms, with inactivation of disinfectants.</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 54px;\">525452</td>\r\n<td style=\"width: 29.8603%; height: 54px;\">Contact Slide 10 (ROSE BENGAL CAF AGAR + NEUTRALIZING / VOGEL JOHNSON AGAR)</td>\r\n<td style=\"width: 57.4051%; height: 54px;\">Yeasts and moulds with inactivation of disinfectants, staphylococci.</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 54px;\">525292</td>\r\n<td style=\"width: 29.8603%; height: 54px;\">Contact Slide Chrom 1 (Chromatic&trade; E.coli-coliform / Chromatic&trade; Salmonella)</td>\r\n<td style=\"width: 57.4051%; height: 54px;\">Chromogenic selective media for detecting <em>E. coli,</em> coliforms and <em>Salmonella spp.</em> on surfaces or in food<br />and waters.</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 54px;\">525392</td>\r\n<td style=\"width: 29.8603%; height: 54px;\">Contact Slide Chrom 2 (Chromatic&trade; E.coli-coliform / PCA+TTC + NEUTRALIZING)</td>\r\n<td style=\"width: 57.4051%; height: 54px;\">Chromogenic selective medium for detecting <em>E. coli</em>, coliforms and for total bacterial count.</td>\r\n</tr>\r\n<tr style=\"height: 72px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 72px;\">525462</td>\r\n<td style=\"width: 29.8603%; height: 72px;\">Contact Slide Chrom 3 (Chromatic&trade; E.coli-coliform / BAIRD PARKER AGAR + NEUTRALIZING)</td>\r\n<td style=\"width: 57.4051%; height: 72px;\">Chromogenic selective medium for detecting <em>E. coli</em>, coliforms and <em>Staphylococcus aureus</em> with inactivation of disinfectants.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">525472</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contact Slide TSA + Neutralizing / TSA + Neutralizing</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Flexible Contact Slide for microbial screening of surfaces (ISO 18593)</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">525482</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contact Slide TSA + Neutralizing / Rose Bengal CAF Agar + Neutralizing</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Flexible Contact Slide for microbial screening of surfaces (ISO 18593)</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71680</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">FOOD SYSTEM</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for detection and presumptive identification of pathogenic microorganisms from foodstuffs. The system provides detection and presumptive identification of: <em>Salmonella spp.</em>, <em>Proteus spp.</em> / <em>Providencia spp.</em>, <em>Pseudomonas spp.</em>,<em> Staphylococcus aureus</em>, <em>E. coli</em>, <em>Bacillus cereus</em>, <em>Listeria spp</em>., yeasts and moulds, and particularly it is <strong>validated to ISO 16140 standard</strong> for<br />the detection of <em>Salmonella spp.</em> and <em>Listeria spp.&nbsp;</em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">71655</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">HACCP SYSTEM Plus</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">System for determination of total microbial count and search for and presumptive identification of pathogenic germs that can be isolated from work surfaces. Specifically, the system provides for the search for and presumptive identification of: <em>Salmonella spp</em>., <em>Citrobacter spp</em>., <em>Proteus spp</em>. <em>Pseudomonas spp</em>., <em>Escherichia coli,</em> <em>Listeria spp</em>., <em>Staphylococcus aureus</em>, yeasts and moulds.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">79700</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">MAIA Pesticide MultiTest</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Colorimetric system for the detection of organophosphate, organochloride and carbamate pesticides residues in soil, water, food and drink.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">86001</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">CLEAN TEST</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">CLEAN TEST is a swab for the detection of protein, fat and sugar residues suitable for the check of work surfaces cleaning level.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">86102</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contam Swab Listeria</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Detection of <em>Listeria spp.</em> directly from surfaces.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">86101</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contam Swab E.coli-coliforms</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Detection of <em>Escherichia coli</em> and other coliform directly from surfaces.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">86103</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contam Swab Salmonella</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Detection of <em>Salmonella spp</em>. directly from surfaces.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">86100</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contam Swab Contamination</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Microbiological test with culture medium and growth indicator (TTC) for the microbial load assay directly from surfaces.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">86104</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contam Swab MRSA</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Detection of Methicillin-resistant <em>Staphylococcus aureus</em> directly from surfaces.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">86105</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Contam Swab Yeasts &amp; Moulds</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Detection of yeasts and moulds directly from surfaces.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\" width=\"107\">PC010</td>\r\n<td style=\"width: 29.8603%;\" width=\"355\">PATH-CHEK Coliform Detection Broth (3 ml)</td>\r\n<td style=\"width: 57.4051%;\">A range of swabs for the detection of Coliform from environmental surfaces.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">PC080</td>\r\n<td style=\"width: 29.8603%;\">PATH-CHEK Listeria Detection Broth (3 ml)</td>\r\n<td style=\"width: 57.4051%;\">A range of swabs for the detection of <em>Listeria monocytogenes</em> from environmental surfaces.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">PC020</td>\r\n<td style=\"width: 29.8603%;\">PATH-CHEK Salmonella Detection Broth (3 ml)</td>\r\n<td style=\"width: 57.4051%;\">A range of swabs for the detection of <em>Salmonella</em> from environmental surfaces.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">PCS100</td>\r\n<td style=\"width: 29.8603%;\">PATH-CHEK Pre-moistened Swabs</td>\r\n<td style=\"width: 57.4051%;\">Pre-moistened swabs increase recovery from wet and dry surfaces. Also neutralises residual detergents and sanitising agents, preserving target microorganisms</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">PC006-100</td>\r\n<td style=\"width: 29.8603%;\">Path- Chek Hygiene Protein</td>\r\n<td style=\"width: 57.4051%;\">A rapid test for the detection of food residues from environmental surfaces or processing equipment.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85601</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ESC Swab Neutralizing Rinse Solution 10 mL</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">ESC (Easy Surface Checking) swab (ISO 18593, ISO 17604) Neutralizing Rinse Solution</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85603</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ESC Swab Buffered Peptone Water 10 mL</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">ESC (Easy Surface Checking) swab (ISO 18593, ISO 17604) Buffered Peptone Water</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85605</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ESC Swab D/E Neutralizing Broth 10 mL</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">ESC (Easy Surface Checking) swab (ISO 18593, ISO 17604) D/E Neutralizing Broth</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85607</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ESC Swab Letheen Broth 10 mL</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">ESC (Easy Surface Checking) swab (ISO 18593, ISO 17604) Letheen Broth</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85609</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">ESC Swab Maximum Recovery Diluent 10 mL</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">ESC (Easy Surface Checking) swab (ISO 18593, ISO 17604) Maximum Recovery Diluent</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">96762</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Sampling Template 10x10 Sterile</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Sampling Template 10x10 is a sterile plastic device used to delimit an area of 100 cm2 for surfaces hygiene monitoring.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">630600</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Water Detect COLIFORMS</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Chromogenic medium used for the simultaneous detection of total coliforms and <em>Escherichia coli</em> in the microbiological monitoring of water quality.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80356</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">MeRA Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Microbiological test with spores of <em>Geobacillus stearothermophilus</em><br />for the detection of antibiotic and sulphamide residues in meat.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">80355</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">MiRA Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Microbiological test with spores of <em>Geobacillus stearothermophilus</em><br />for the detection of antibiotic and sulphamide residues in milk.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">11200</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">PAR TEST Agar</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Medium with spores of <em>Geobacillus stearothermophilus</em> for residual antibiotic detection in biological liquids (milk, blood and urine).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">20157</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SWAB Solution SKELETON</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Solutions for sample collection</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">20160</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SWAB Solution SURFACES</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Solutions for sample collection</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\" width=\"64\">85307</td>\r\n<td style=\"width: 29.8603%; height: 18px;\" width=\"584\">BIO &ndash; CULT AMIES + charcoal</td>\r\n<td style=\"width: 57.4051%; height: 18px;\" width=\"172\">Swabs w/ and w/o transport Medium</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85317</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">BIO &ndash; CULT AMIES</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Swabs w/ and w/o transport Medium</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85306</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">BIO &ndash; CULT STUART + charcoal</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Swabs w/ and w/o transport Medium</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85308</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">BIO &ndash; CULT STUART</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Swabs w/ and w/o transport Medium</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85270</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Sterile Swab in Envelope</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Swabs w/ and w/o transport Medium</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">85275</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Sterile Swab without envelope</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Swabs w/ and w/o transport Medium</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\" width=\"107\">M44CE</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; E. coli 0157 Latex Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">A rapid latex slide agglutination test for identifying <em>E. coli</em> 0157 grown on selective medium.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">F46</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Campylobacter Latex Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid and simple latex test for the confirmation of enteropathogenic Campylobacters grown in enrichment broths or selective plates. Recommended for food testing.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">F42</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Salmonella Latex Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">A rapid, latex slide agglutination test for the presumptive identification of Salmonella in selective and / or enrichment cultures or isolates taken directly from selective agars. Suitable for clinical and food use.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">F48</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Listeria Latex Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid slide latex test for the identification of motile <em>Listeria spp.</em> On solid selective media. Recommended for food testing.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 12.7345%; text-align: center;\">M45</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">Microgen&reg; Legionella Latex Test</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">rapid latex slide agglutination50 teststest for the confirmatory identification of <em>L. pneumophila</em> serogroup 1 and serogroup 2 - 15 and non- <em>L. pneumophila</em> species of clinical significance grown onselective media.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\" width=\"64\">96143</td>\r\n<td style=\"width: 29.8603%; height: 36px;\" width=\"584\">CAMPYLOBACTER latex kit</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Rapid agglutination test for direct identification of <em>Campylobacter jejuni.</em></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">96150</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">E. coli 0157 latex kit</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Rapid agglutination test for direct identification of <em>Escherichia coli</em> O157.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">96151</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">SALMONELLA latex kit</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid agglutination test for direct identification of <em>Salmonella spp.</em></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">96017</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">STAPH latex kit</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Rapid agglutination test for direct identification of <em>Staphylococcus aureus. </em></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">96144</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">CLOSTRIDIUM DIFFICILE latex kit</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Rapid agglutination test for direct identification of <em>Clostridium difficile.</em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">96142</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">LEGIONELLA latex kit</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid agglutination test for direct identification of <em>Legionella spp. </em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 18px;\">96146</td>\r\n<td style=\"width: 29.8603%; height: 18px;\">LISTERIA latex kit</td>\r\n<td style=\"width: 57.4051%; height: 18px;\">Rapid agglutination test for direct identification of <em>Listeria spp. </em></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">96153</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">STREPTO B latex kit</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Rapid test for Group B Streptococci identification (<em>Streptococcus agalactiae</em>)</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">96154</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">STREPTO A latex kit</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Rapid agglutination test for direct identification of Group A Streptococcus.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 36px;\">96016</td>\r\n<td style=\"width: 29.8603%; height: 36px;\">STREP-CHECK KIT</td>\r\n<td style=\"width: 57.4051%; height: 36px;\">Rapid agglutination test for direct identification of <em>Streptococci, Lancefield&rsquo;s</em> Groups A, B, C, D, F and G.</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 54px;\">96148</td>\r\n<td style=\"width: 29.8603%; height: 54px;\">SHIGELLA ANTISERUM</td>\r\n<td style=\"width: 57.4051%; height: 54px;\">Lyophilized polyvalent serum for direct serological characterization of <em>Shigella spp.</em> and for confirmation of the isolation on COPRO SYSTEM plus</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 12.7345%; text-align: center; height: 54px;\">96147</td>\r\n<td style=\"width: 29.8603%; height: 54px;\">YERSINIA ENTEROCOLITICA ANTISERUM</td>\r\n<td style=\"width: 57.4051%; height: 54px;\">The test sera are used to identify the serovar of <em>Yersinia enterocolitica</em> strains isolated from test material of human and animal origin by means of slide agglutination.</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 'db85330e6f952d703bf5086488c1be53.jpg', '', '2019-09-09 23:00:14', '2020-03-08 21:07:00', 1, '2020-03-08 00:00:00', 'blog', '', '', '', 0);
INSERT INTO `web_content` (`content_id`, `channel_id`, `content_cat_id`, `title`, `title_eng`, `description`, `description_eng`, `file`, `file_eng`, `posted`, `updated`, `status`, `published`, `type`, `param1`, `param2`, `param3`, `ispromo`) VALUES
(160, 40, 0, 'Dairy', '', '<p><strong>The dairy industry</strong> is central to the worldâ€™s food supply chain and so the safety of dairy industry products including milk, butter, cheese and yoghurt is paramount.</p>\r\n<p>Since milk is an ideal medium for the growth of micro-organisms, both pathogenic and non-pathogenic, the dairy industry is faced with the challenge of constantly adapting to ensure their products are of a high quality and are safe for the end consumer.</p>\r\n<p>We offers products to test for microorganisms of concern, such as Listeria spp. as well as solutions for bioburden and spoilage testing. This allows the industry to monitor and control quality to meet the required regulatory standards.</p>\r\n<p>Culture media & reagent for dairy analysis</p>\r\n<table style=\"border-collapse: collapse; width: 100.846%; height: 2371px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 31px;\">\r\n<td style=\"width: 10.1496%; height: 31px; text-align: center;\"><strong>Catalogue</strong></td>\r\n<td style=\"width: 24.1749%; height: 31px; text-align: center;\"><strong>Product</strong></td>\r\n<td style=\"width: 77.1066%; height: 31px; text-align: center;\"><strong>Application</strong></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\" width=\"64\">610314</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">ANTIBIOTIC Agar No.1</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Used in antibiotic assay work (USP, FDA, Ph Eur) according to Grove & Randall; the medium can be used as seed agar, e.g. withÂ <em>S. aureus</em>Â for the assay of kanamycin or as base agar, e.g. for assaying chloramphenicol.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\" width=\"64\">610316</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">ANTIBIOTIC Broth No.3</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Liquid medium used for the determination potency of antibiotics by the microbial assay technique following the USP specifications.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\" width=\"64\">610315</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">ANTIBIOTIC Agar No.11</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">ANTIBIOTIC AGAR nÂ°11 is used for determining antibiotic potency by the microbiological assay technique and is conform with specifications of The United States Pharmacopeia (USP).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610153</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Azide Blood Agar Base</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">A selective medium for the detection and isolation of Streptococci and Staphylococci from stool, sewage, food and other specimens.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610003</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Azide Dextrose Broth</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">For the selective enrichment ofÂ <em>Streptococci</em>. Recommended for detection in milk, water, sewage, feces and other specimens.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610114</td>\r\n<td style=\"width: 24.1749%;\">BACILLUS CEREUS Agar Base (MOSSEL, MYP)</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Basal medium for the isolation and enumeration of <em>Bacillus cereus</em>, according to ISO 7932, ISO 21871 and FDA-BAM.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610136</td>\r\n<td style=\"width: 24.1749%;\">BACILLUS CEREUS Agar Base (PEMBA)</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Selective medium for <em>Bacillus cereus</em> isolation and enumertion in foodstuffs.Â </td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610004</td>\r\n<td style=\"width: 24.1749%;\">Baird Parker Agar Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Selective medium for detection and enumeration of coagulase-positive staphylococci in food and animal feed, according to ISO 6888.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610188</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Blood Agar Base No.2</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Formulated to yield maximum recovery of fastidious pathogenic microorganisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610009</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Brilliant Green Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">A highly selective medium for the isolation and identification of Salmonella except S. typhosa or Shigella species.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610010</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Brilliant Green Bile Broth 2%</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">For the selective enrichment and enumeration by titer determination or MPN method ofÂ <em>E. coli</em>Â and other fecal coliform from water, milk, food and other material.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610079</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Brucella Broth</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Recommended for enrichment, isolation and cultivation ofÂ <em>Brucella</em>Â species.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610142</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">BRYANT AND BURKEY Medium</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Bryant and Burkey Medium is used for detecting and enumerating spores of lactate fermenting Clostridium in milk and dairy products.</td>\r\n</tr>\r\n<tr style=\"height: 108px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 108px;\">611014</td>\r\n<td style=\"width: 24.1749%; height: 108px;\">Buffered Peptone Water</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 108px;\">Liquid medium recommended by ISO 6579 for increasing the recovery of injured Salmonella spp. from food and associated samples prior to selective enrichment and isolation. According to ISO 21528, Buffered Peptone Water is used for detection or enumeration of Enterobacteriaceae within foodstuffs. Used as diluent, Buffered Peptone Water complies with ISO 6887 and 11290 for the enumeration of organisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">611007</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Campylobacter Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">For the isolation of Campylobacter species from human and animal derived clinical material, and from contaminated food, water etc.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">611007</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Campylobacter Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Used for selective isolation and differentiation of Campylobacter species.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610130</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Campylobacter Blood FREE Medium Base</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Used for selective isolation and differentiation ofÂ <em>Campylobacter</em>Â species.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610131</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Campylobacter ENRICHMENT Broth Base</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Used for selective isolation and differentiation ofÂ <em>Campylobacter</em>Â species.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610200</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Campylobacter KARMALI Agar Base</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Used for selective isolation and differentiation ofÂ <em>Campylobacter</em>Â species.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610041</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">CETRIMIDE Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">For the isolation and differentiation ofÂ <em>Pseudomonas aeruginosa</em> from different material.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\" width=\"64\">610362</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">CHINA-BLUE Lactose Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Selective medium for differentiating lactose fermenting and lactose non-fermenting microorganisms.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610628</td>\r\n<td style=\"width: 24.1749%;\">Chromaticâ„¢ Bacillus cereus</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Chromogenic medium for detection of <em>Bacillus cereus</em> in food and environmental samples.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610390</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Chromaticâ„¢ Cronobacter Isolation Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">chromogenic medium used for the isolation of <em>Cronobacter spp.</em> (formerly Enterobacter sakazakii) from food, animal feed and environmental samples in areas of food production and handling. According to ISO 22964:2017, CCI is used in conjunction with Cronobacter Selective Broth (CSB).</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610630</td>\r\n<td style=\"width: 24.1749%;\">Chromaticâ„¢ Coliform Agar ISO</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Chromogenic medium for detection and enumeration of <em>E. coli</em> and coliform bacteria in water, according to ISO 9308-1.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610610</td>\r\n<td style=\"width: 24.1749%;\">Chromaticâ„¢ Coli/Coliform</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Chromogenic medium for detection and enumeration of <em>Escherichia coli</em> and coliform bacteria in food and water.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610601</td>\r\n<td style=\"width: 24.1749%;\">O.A. Listeria Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Chromogenic selective medium for <em>Listeria monocytogenes</em> isolation and differentiation (ISO 11290).</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610611</td>\r\n<td style=\"width: 24.1749%;\">Chromaticâ„¢ Salmonella</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Chromogenic selective medium for isolation and differentiation of <em>Salmonella</em> <em>spp.</em> (including <em>S. typhi</em>).</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610616</td>\r\n<td style=\"width: 24.1749%;\">Chromaticâ„¢ Staph aureus</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Chromogenic medium for the isolation and differentiation of <em>Staphylococcus</em> <em>aureus</em> directly from clinical and nonclinical specimens.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610224</td>\r\n<td style=\"width: 24.1749%;\">TBX Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Chromogenic medium for detection and enumeration of <em>E. coli,</em> according to ISO 16649 (all parts).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610056</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Clostridium Broth</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Medium for the cultivation and the enumeration of clostridia and other anaerobes from foods and clinical samples.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610207</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Clostridium Perfringens Agar Base</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Basal medium for detection of C. perfringens from clinical specimens and other materials according to ISO 7937 and ISO 14189.</td>\r\n</tr>\r\n<tr style=\"height: 90px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 90px;\" width=\"64\">610372</td>\r\n<td style=\"width: 24.1749%; height: 90px;\">Cooked Meat Medium</td>\r\n<td style=\"width: 77.1066%; height: 90px; text-align: justify;\">Medium for the cultivation and maintenance of anaerobic organisms, especially pathogenic clostridia, differentiating saccharolytic from proteolytic species. This medium permits growth from a small inoculum, important for clinical specimens. It is also recommended in standard methods for food testing for the enumeration and identification of Clostridium perfringens.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610389</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Cronobacter Selective Broth</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Selective liquid medium for detection of <em>Cronobacter spp</em>, according to ISO 22964:2017.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610091</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Demi Fraser Broth</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Medium for primary enrichment of <em>Listeria spp.</em> according ISO 11290.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610198</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Dextrose Tryptone Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Medium for cultivating thermophilic â€œflat sourâ€ microorganisms from food spoilage.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610238</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Dichloran-Glycerol (DG18) Agar Base</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Selective medium for the enumeration of yeasts and moulds, according to ISO 21527-2:2008.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610237</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Dichloran Rose-Bengal Chloramphenicol Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Selective medium for the enumeration of yeasts and moulds, according to ISO 21527-1:2008.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610063</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">E.C. Broth</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Selective liquid medium for detection and enumeration of coliform bacteria and <em>E. coli</em> in water and food, according to ISO 7251.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 36px;\">610332</td>\r\n<td style=\"width: 24.1749%; height: 36px;\">E.C. Broth MUG</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 36px;\">Selective broth for fecal coliforms and E. coli detection in water, wastewater, shellfish and foods.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610017</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">E.E. Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Liquid medium for the cultivation and selective enrichment of Enterobacteriaceae from different types of samples, according to USP/EP/JP.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610019</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">E.M.B. LEVINE Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for gram-negative enteric bacteria isolation (harmonized US Pharmacopeia)</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610020</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">ENDO Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for coliforms confirmatory test.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; height: 18px; text-align: center;\">610623</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Enterobacter (Cronobacter) sakazakii Isolation Agar</td>\r\n<td style=\"width: 77.1066%; height: 18px; text-align: justify;\">Enterobacter (Cronobacter) sakazakii Isolation Agar is a chromogenic medium used for the selective isolation of<br />Cronobacter spp (formerly E. sakazakii) in infant milk products, according to ISO 22964:2006.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610375</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Fraser Broth Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Enrichment medium for detection and enumeration of Listeria monocytogenes and Listeria spp, according to ISO 11290 (both parts).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610054</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Gelatin Peptone Agar (Agar gelisato)</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for the cultivation of non-fastidious organisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610100</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Giolitti Cantoni Broth Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Basal medium for <em>Staphylococcus aureus</em> enrichment from foods, recommended by ISO 6888-3: 2003</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610388</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Glucose OF Medium ISO 21528</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Glucose OF medium is a semisoild medium used for the identification of gram-negative bacteria on the basis of their ability to oxidize or ferment glucose. This medium complies with ISO 21528:2017 for confirmation of Enterobacteriaceae from food, animal feeding stuffs and environmental samples.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">611021</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Heart Infusion Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Heart Infusion Broth is used for general laboratory purpose for the cultivation of fastidious organisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610021</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Hektoen Enteric Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective and differential medium for detection of pathogenic intestinal bacteria from food and clinical specimens, according to ISO 21567.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610190</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Kanamycin Aesculin Azide Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for isolation of enterococci in foods and foodstuffs.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">611202</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Lactose Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Recommended for use in the presumptive test for members of the coliform group in water, milk and other material. It corresponds largely to the formulation of the United States Pharmacopoeia.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610360</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Lactose GELATIN Medium</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Dehydrated medium for the identification of <em>C. perfringens</em> by lactose and gelatin test (ISO 7937).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610358</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Lactose Sulfite Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Liquid medium for detection of <em>C. perfringens</em>, according to EP and ISO 7937.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610247</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Lauryl Sulfate Tryptose Broth Modified (m-LST)</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective liquid medium for detection of <em>Cronobacter spp</em>, according to ISO 22964:2006.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610085</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">LAURYL TRYPTOSE Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium acc. to Mallmann and Darby (1941) for the presumptive testing for coliform and their selective enrichment in the examination of water, dairy products and food.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610326</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Listeria Enrichment Broth Base (Lovett)</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Broth for enrichment of Listeria spp. according to Lovett\'s formulation.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610166</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Listeria FRASER Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for secondary enrichment of <em>Listeria spp</em>.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610167</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Listeria Oxford Agar Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for <em>Listeria spp</em> isolation and differentiation in foods, milk and dairy products and clinical and environmental samples (ISO 10560:1993).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610231</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Listeria Oxford Agar Base ISO 11290</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Basal medium without antibiotics and acriflavine for the isolation of <em>Listeria monocytogenes</em> according to ISO 11290.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610168</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Listeria PALCAM Agar Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for the isolation and enumeration of <em>Listeria monocytogenes</em> according to ISO 11290-1.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610031</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Listeria UVM 1 Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for <em>Listeria spp</em> enrichment.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610045</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Listeria UVM 2 Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for <em>Listeria spp</em> enrichment.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610318</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">LITMUS MILK</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Litmus milk is used for the maintenance of lactic acid bacteria and as a differential medium for determining the action of bacteria on milk.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610303</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Lysine DECARBOXYLASE Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Dehydrated medium used for identification of microorganisms, especially enteric bacilli, based on the decarboxylation of lysine</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610027</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Lysine IRON Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Differential medium for enterobacteria isolation.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610192</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">M17 Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for selective enumeration of Streptococcus thermophilus and for the improved growth of lactic streptococci and their bacteriophages.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610018</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">M.S.R.V. (Modified Semisolid Rappaport Vassiliadis) Medium Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for detection of motile <em>Salmonella spp</em> in animal faeces and environmental samples, according to ISO 6579.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610337</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">MacConkey Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">A presumptive medium for the detection of the coliform group in water and milk.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610171</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">MacConkey Broth (Purple)</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">MacConkey Broth Purple is a differential medium used for the detection of coliforms in water samples and milk examination by MPN technique. It is a modification of the classic medium, where neutral red is replaced by a less aggressive indicator, according European Pharmacopoeia. It is also recommended by ISO Committee under the specification ISO 9308-2:1990.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610172</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Malonate Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Recommended for the differentiation ofÂ <em>Enterobacter</em>Â andÂ <em>Escherichia</em>.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610101</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Malt Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Used for the detection and isolation of yeasts and molds from dairy products and foods.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610173</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Malt Extract Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">A medium for the isolation and enumeration of yeasts and molds.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610069</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Malt Extract Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">A liquid medium for the cultivation of yeasts and molds.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610235</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Mannitol MOTILITY Test Medium</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Semisolid medium used for the detection of motility of Enterobacteriaceae</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610077</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Maximum Recovery Diluent</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Diluent for preparation of food samples for microbiological examination, according to ISO 6887.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610073</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Milk Plate Count Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for the enumeration of microorganisms in milk and dairy products, according to the APHA and ISO 4833.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610396</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Mineral Modified Glutamate Medium</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Liquid selective enrichment medium for the enumeration of <em>Escherichia coli</em>, according to ISO 16649.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610236</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Motility Indole Urea Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium used for differentiating Enterobacteriaceae based on motility, indole production and urease activity</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610371</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Motility Nitrate CP Medium</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">For the identification of <em>Clostridium perfringens</em>, according to ISO 7937.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610132</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Motility TEST Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Dehydrated medium for detection of motility of gram-negative enteric bacilli according to UNI EN ISO 11290-1:2005.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610032</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">MR-VP Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for Gram-negative bacteria differentiation, recommended by ISO 6785: 2001 and IDF 93: 2001.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610024</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">MRS Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">For the enrichment, cultivation and isolation of all species ofÂ <em>Lactobacillus</em>Â from all types of material according to DeMan, Rogosa and Sharpe.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610025</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">MRS Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">For the enrichment and isolation of all species of Lactobacilli from all types of material.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610035</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Muller Kauffmann Broth Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Basal medium for Salmonella selective enrichment from water, foodstuffs and fecal samples.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610239</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Muller Kauffmann TETRATHIONATE Broth Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Basal medium for detection of <em>Salmonella spp</em> from foodstuffs and environmental samples, according to ISO 6579.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610036</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Nutrient Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for cultivating non-fastidious organisms and confirming <em>Pseudomonas aeruginosa</em>, according to ISO 16266.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610037</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Nutrient Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Liquid medium for the cultivation of nonfastidious microorganisms.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610217</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Nutrient Broth no.2</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Liquid medium recommended for sterility testing of aerobic organisms as well as a base for the enrichment of special media.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610202</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">O.G.Y.E. Agar Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective agar according to Mossel for the identification and enumeration of yeasts and other fungi in foods, clinical specimens etc.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610038</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Peptone Water</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for cultivation of non-fastidious microorganisms and indole testing as recommended by ISO 7251.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610040</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Plate Count Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for the enumeration of bacteria in food, water and other materials, according to APHA and ISO 4833.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 36px;\">610102</td>\r\n<td style=\"width: 24.1749%; height: 36px;\">POTATO Dextrose Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 36px;\">Recommended for the isolation and enumeration of yeasts and molds in dairy products and food.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610071</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Pseudomonas Agar Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for detection and enumeration of <em>Pseudomonas spp</em>, according to ISO 13720, ISO/TS 11059 and ISO 16266.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610175</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">RAPPAPORT VASSILIADIS Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Used as a selective enrichment medium for the isolation ofÂ <em>SalmonellaÂ </em>species from food and environmental specimens.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610096</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">REINFORCED CLOSTRIDIAL Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for isolation and enumeration of anaerobes and Clostridium spp recommended by ISO 6461/1.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610176</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Rogosa Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective agar for the isolation and enumeration of lactobacilli belonging to the buccal and intestinal flora, as well as from food such as milk and meat.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610178</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Rose Bengal Agar Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">For the selective isolation and enumeration of yeasts and moulds from environmental materials and food stuffs.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610150</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Selenite CYSTINE Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Liquid medium for detection of Salmonella spp according to ISO 6785.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610046</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">SIMMONS CITRATE Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Differential medium for enterobacteria identification.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610055</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">T.S.I. Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Differential medium for enterobacteria identification.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610052</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Tryptic Soy Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">General purpose medium for the cultivation of a wide variety of organisms from clinical and nonclinical specimens, according to EN ISO 11133.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610053</td>\r\n<td style=\"width: 24.1749%;\">Tryptic Soy Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Highly nutrient liquid medium for the general purposes, formulated according to USP, FDA and Eur. Phar.regulations.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610206</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Tryptone Water</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Liquid medium for detection of <em>E. coli</em> in clinical specimens, food and water samples, according to ISO 7251and ISO 3811.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610349</td>\r\n<td style=\"width: 24.1749%;\">TSYE Agar (Tryptic Soy Yeast Extract Agar)</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Medium for detection of <em>Listeria spp</em> in food, according to ISO 11290-1.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610241</td>\r\n<td style=\"width: 24.1749%;\">Tryptone Soya Yeast Extract Broth</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Liquid culture medium for the confirmation of <em>Listeria monocytogenes</em> according to ISO 11290.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610107</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">UREA Agar Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Medium for urease test, recommended by ISO 6785 and IDF 93.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 10.1496%; text-align: center;\">610186</td>\r\n<td style=\"width: 24.1749%;\">Vogel Johnson Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify;\">Selective basal medium for <em>Staphylococcus aureus</em> isolation.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 36px;\">610187</td>\r\n<td style=\"width: 24.1749%; height: 36px;\">Violet Red Bile Agar MUG</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 36px;\">Selective medium for isolation and counting coliforms and <em>E. coli</em> in foodstuffs.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610059</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Violet Red Bile Glucose Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for detection and enumeration of Enterobacteriaceae in food, water and other materials, according to USP/EP/JP and ISO 21528.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610058</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Violet Red Bile Lactose Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for the enumeration of coliforms in food, water and other materials, according to APHA and ISO 4832.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610060</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">XLD Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for detection of <em>Salmonella</em> and <em>Shigella spp</em> in food, environmental samples and other materials, according to ISO 6579 and ISO 21567.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610092</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">XLT 4 Agar Base</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective medium for non-typhi <em>Salmonella</em> isolation.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 10.1496%; text-align: center; height: 18px;\">610070</td>\r\n<td style=\"width: 24.1749%; height: 18px;\">Yeast Glucose Chloramphenicol Agar</td>\r\n<td style=\"width: 77.1066%; text-align: justify; height: 18px;\">Selective agar for the enumeration and isolation of yeasts and molds in dairy products.</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', '2308f7b4202302034c7c5f5c578e6579.jpg', '', '2019-09-09 22:39:18', '2019-10-14 17:32:14', 1, '2019-10-14 00:00:00', 'blog', '', '', '', 0);
INSERT INTO `web_content` (`content_id`, `channel_id`, `content_cat_id`, `title`, `title_eng`, `description`, `description_eng`, `file`, `file_eng`, `posted`, `updated`, `status`, `published`, `type`, `param1`, `param2`, `param3`, `ispromo`) VALUES
(179, 44, 0, 'Water', '', '<p>The safety of water is one of the most important public health concerns. Routine microbiological analysis allows for confidence of water safety and best deployment of resources to effectively manage risk.</p>\r\n<p>Microbiological analysis of water is largely based on the detection of indicator organisms that specify faecal contamination of water.</p>\r\n<p>We offers solutions to help water industry laboratories and external laboratories test according to both directive and national requirements, as well as international standards such as ISO.</p>\r\n<p>Culture media &amp; reagent for Water analysis</p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 3521px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 29px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 29px;\"><strong>Catalogue</strong></td>\r\n<td style=\"width: 29.1417%; text-align: center; height: 29px;\"><strong>Product&nbsp;</strong></td>\r\n<td style=\"width: 56.3273%; text-align: center; height: 29px;\"><strong>Application</strong></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610105</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">A1 Medium</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">For detecting faecal coliforms in water samples waste water, sea water and foods by a MPN method.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610048</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">AEROMONAS Agar Base</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Basal medium for selective isolation of Aeromonas spp from clinical and environmental samples.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610138</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">ASPARAGINE ENRICHMENT Broth</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Medium for <em>Pseudomonas aeruginosa</em> detection in pool and bathing waters.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610153</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Azide Blood Agar Base</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Selective basal medium for streptococci and staphylococci isolation from feces, waters and foods.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610003</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Azide Dextrose Broth</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Selective medium for fecal streptococci detection and enumeration in waters and foodstuffs.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 18px;\" width=\"64\">610154</td>\r\n<td style=\"width: 29.1417%; height: 18px;\" width=\"584\">Azide MaltOSE Agar KF</td>\r\n<td style=\"width: 56.3273%; height: 18px;\">Selective medium for fecal streptococci detection and enumeration in waters and foodstuffs</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610004</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Baird Parker Agar Base</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">For the isolation and differentiation of&nbsp;<em>Staphylococci&nbsp;</em>in food and pharmaceuticals according to Baird-Parker.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610210</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Bile Aesculin Agar</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Differential medium for group D streptococci isolation in foods and pharmaceutical products.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610301</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">BISMUTH Sulfite Agar</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Dehydrated medium for the isolation and differentation of <em>Salmonella typhi</em> and other salmonellae</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610005</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Blood Agar Base</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">A non-selective medium for the isolation and cultivation of many pathogenic and non-pathogenic microorganisms.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610007</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Brain Heart Infusion Agar</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">A solid medium for the cultivation of fastidious pathogenic bacteria such as&nbsp;<em>Streptococci</em>&nbsp;and&nbsp;<em>Neisseria</em>.</td>\r\n</tr>\r\n<tr style=\"height: 90px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 90px;\" width=\"64\">610008</td>\r\n<td style=\"width: 29.1417%; height: 90px;\" width=\"584\">Brain Heart Infusion Broth</td>\r\n<td style=\"width: 56.3273%; height: 90px;\">Brain Heart Infusion Broth is recommended for the cultivation of fastidious pathogenic microorganisms. Brain Heart Infusion Broth has been used as culture medium for<em>Streptococcus pneumonia</em>,<span id=\"1191534\"></span>&nbsp;<em>Listeria monocytogenes</em>,<span id=\"1191535\"></span>&nbsp;<em>Leishmania promastigotes</em><span id=\"1191536\"></span>&nbsp;and&nbsp;<em>Clostridium difficile</em>.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">620009</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Brilliant Green Agar</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Selective medium for isolation of&nbsp;<em>salmonellae</em>&nbsp;from clinical specimens and other materials of sanitary importance.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610010</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Brilliant Green Bile Broth 2%</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Liquid medium for detection or confirmation of coliform bacteria<br />in water and food, according to APHA, ISO 4831 and ISO 4832.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 18px;\" width=\"64\">610079</td>\r\n<td style=\"width: 29.1417%; height: 18px;\" width=\"584\">Brucella Agar Base</td>\r\n<td style=\"width: 56.3273%; height: 18px;\">Basal medium for selective isolation of <em>Brucella spp.</em></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610356</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Brucella Broth</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Dehydrated medium for the cultivation of <em>Brucella spp</em> and other fastidious microorganisms</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">611007</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Campylobacter Agar</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Selective medium for Campylobacter spp isolation from clinical samples.</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 54px;\" width=\"64\">610052</td>\r\n<td style=\"width: 29.1417%; height: 54px;\" width=\"584\">Tryptic Soy Agar</td>\r\n<td style=\"width: 56.3273%; height: 54px;\">General purpose medium for the cultivation of a wide variety of organisms from clinical and nonclinical specimens, according to EN ISO 11133.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610053</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Tryptic Soy Broth</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Liquid medium for the isolation and cultivation of a wide variety of organisms, according to USP/EP/JP.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610041</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">CETRIMIDE Agar</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Selective medium for&nbsp;<em>Pseudomonas aeruginosa</em>&nbsp;isolation, according to European Pharmaacopoeia.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610012</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Cled Agar</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Medium for the isolation, enumeration and differentiation of pathogenic bacteria in urine specimens.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610056</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Clostridium Broth</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">edium for the cultivation and the enumeration of clostridia and other anaerobes from foods and clinical</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610013</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">Columbia Agar Base</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Medium for fastidious microorganisms isolation from clinical samples.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 18px;\" width=\"64\">610372</td>\r\n<td style=\"width: 29.1417%; height: 18px;\" width=\"584\">Cooked Meat Medium</td>\r\n<td style=\"width: 56.3273%; height: 18px;\">Medium for the cultivation of anaerobes, from clinical and nonclinical samples.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610095</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">CZAPEK DOX Agar</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Medium for cultivating fungi and bacteria from clinical specimens and environmental samples.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 18px;\" width=\"64\">610072</td>\r\n<td style=\"width: 29.1417%; height: 18px;\" width=\"584\">CZAPEK DOX Broth</td>\r\n<td style=\"width: 56.3273%; height: 18px;\">Selective medium for saprophytic fungi cultivation.</td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 54px;\" width=\"64\">610063</td>\r\n<td style=\"width: 29.1417%; height: 54px;\" width=\"584\">E.C. Broth</td>\r\n<td style=\"width: 56.3273%; height: 54px;\">Selective liquid medium for detection and enumeration of<br />coliform bacteria and <em>E. coli</em> in water and food, according to ISO 7251.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">610332</td>\r\n<td style=\"width: 29.1417%; height: 36px;\" width=\"584\">E.C. Broth MUG</td>\r\n<td style=\"width: 56.3273%; height: 36px;\">Selective broth for fecal coliforms and <em>E. coli</em> detection in water, wastewater, shellfish and foods.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 14.5309%; text-align: center; height: 36px;\" width=\"64\">61001