INSERT INTO `web_content` (`content_id`, `channel_id`, `content_cat_id`, `title`, `title_eng`, `description`, `description_eng`, `file`, `file_eng`, `posted`, `updated`, `status`, `published`, `type`, `param1`, `param2`, `param3`, `ispromo`) VALUES
(181, 26, 0, 'Lab Design', '', '<p><strong>Lab Design and Furnishings</strong></p>\r\n<p class=\"\"><strong>ProDesign</strong> objective is simple: provide superior quality laboratory products and hands-on customer service through our highly skilled and knowledgeable sales representatives, project managers, and design specialists. We continue to provide that top quality service while building personal relationships with Owners, Architects, Contractors, and Suppliers. </p>\r\n<p class=\"\"><strong>ProDesign</strong> is a full service sales agency specializing in laboratory furniture for the public and private sector industry. We offer a variety of equipment to meet any need including: painted metal casework, stainless steel casework, wood casework, polypropylene casework and plastic laminate casework; chemical fume hoods, flexible lab furniture, epoxy countertops, phenolic countertops, stainless steel countertops; sinks, fixtures and related laboratory products.</p>\r\n<p class=\"\">Whether your project includes new construction or remodel, ProDesin is the key to your lab needs.</p>\r\n<p class=\"\"> </p>\r\n<p class=\"\">Our completed lab design project:</p>\r\n<p class=\"\">1. PT. Galic Bina Mada</p>\r\n<p class=\"\"><img src=\"/content/photo/3f9abf496b160474234c22146fb9d3a0.jpg\" alt=\"\" width=\"409\" height=\"230\" /><img src=\"/content/photo/688f4efe0c7541af9cddbec85318c52f.jpg\" alt=\"\" width=\"306\" height=\"230\" /></p>\r\n<p class=\"\"><img src=\"/content/photo/eaa3a1ffecaa229cf57aeb590dc55995.jpg\" alt=\"\" width=\"406\" height=\"228\" /><img src=\"/content/photo/7a22fcccb19c08fd096ab8b4c7f82ad3.jpg\" alt=\"\" width=\"305\" height=\"228\" /></p>\r\n<p class=\"\">2. PT. Sucofindo Cibitung</p>\r\n<p class=\"\"><img src=\"/content/photo/aca5b6950cbb04f69fe855ada1b31f52.jpg\" alt=\"\" width=\"231\" height=\"476\" /><img src=\"/content/photo/2ac5265f01119a223cc07459f7999738.jpg\" alt=\"\" width=\"357\" height=\"476\" /></p>\r\n<p class=\"\"><img src=\"/content/photo/405811e3dec2b6958638833b083798e9.jpg\" alt=\"\" width=\"294\" height=\"221\" /><img src=\"/content/photo/87c1ece3babb23e8d1487c497e107e69.jpg\" alt=\"\" width=\"295\" height=\"222\" /></p>\r\n<p class=\"\"> </p>\r\n<p class=\"\"><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>\r\n<p class=\"\"> </p>\r\n<p class=\"\"> </p>\r\n<p class=\"\"> </p>\r\n<p class=\"\"> </p>\r\n<p class=\"\"> </p>\r\n<p class=\"\"> </p>\r\n<p class=\"\"> </p>\r\n<p class=\"\" style=\"padding-left: 40px;\"> </p>\r\n<p> </p>\r\n<p> </p>', '', '20fcf40f090b770aae2279a83522e25f.jpg', '', '2019-09-11 22:56:45', '2025-12-27 08:08:48', 1, '2025-12-27 00:00:00', 'blog', '', '', '', 0);
INSERT INTO `web_content` (`content_id`, `channel_id`, `content_cat_id`, `title`, `title_eng`, `description`, `description_eng`, `file`, `file_eng`, `posted`, `updated`, `status`, `published`, `type`, `param1`, `param2`, `param3`, `ispromo`) VALUES
(216, 83, 0, 'MICA® Diamidex - Counting Microorganisms Faster', '', '<p>The MICA® system enables early detection and automated CFU enumeration of culturable microorganisms at the micro-colony stage. Laboratories maintain standard membrane filtration workflows while achieving faster decisions, reduced technician workload, and consistent, reproducible results.</p>\r\n<p>After membrane filtration and incubation, the membrane is simply placed into the MICA® system. Using ultra-high-definition imaging, patented probes, and proprietary machine-learning algorithms, MICA® detects and automatically counts target culturable microorganisms at the micro-colony stage—without additional confirmation steps.</p>\r\n<p>Capable of processing up to 500 analyses in just 8 hours, MICA® significantly shortens time-to-results, minimizes human error, and reduces reliance on highly skilled personnel—while maintaining full compliance with culture-based microbiology.</p>\r\n<p>Why it feels different in the lab?<br />1. Culture-based on agar medium, fully culture-based on agar media, ensuring that results are derived from the actual growth of viable microorganisms—not indirect signals or assumptions.<br />2. Faster via micro-colony stage, Acceleration is achieved by initiating enumeration at the micro-colony stage—<em>Pasteurian Culture 2.0</em>—delivering faster, culture-based results expressed in CFU/L.<br />3. Enumeration + detection in one simple run, Colonies labeled with target-specific molecular markers can be automatically counted and identified simultaneously—eliminating the need for additional confirmation steps.<br /><br /><br /><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"data:image/png;base64,\" width=\"498\" height=\"122\" /><br /><br /><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"data:image/png;base64,\" width=\"723\" height=\"539\" /><br /><br /></p>', '', '0d26f3700cc432881f117c7984fe5079.jpg', '', '2025-12-27 09:24:24', '2025-12-27 09:32:41', 1, '2025-12-27 00:00:00', 'blog', '', '', '', 0);
INSERT INTO `web_content` (`content_id`, `channel_id`, `content_cat_id`, `title`, `title_eng`, `description`, `description_eng`, `file`, `file_eng`, `posted`, `updated`, `status`, `published`, `type`, `param1`, `param2`, `param3`, `ispromo`) VALUES
(183, 31, 0, 'Maintenance & Repair', '', '<p><strong>E</strong>quipment maintenance and servicing department boasts engineers certified in various fields and ready to take on any engineering challenges. The team is highly motivated and is constantly on the lookout for the most effective approach towards new problems.</p>\r\n<p>We offer lab equipment installation, adaptation, moving and maintenance services. We are able to modify your existing equipment to new research, choose suitable research methods, consult you on lab equipment care or service it ourselves.</p>\r\n<p>Besides, we are fully aware that learning to use new equipment can be challenging, and therefore are always ready to teach you and offer straightforward explanations.</p>', '', '61ffa0e22f1e0918d921145b2566080c.jpg', '', '2019-12-07 17:04:07', '0000-00-00 00:00:00', 1, '2019-12-07 00:00:00', 'blog', '', '', '', 0),
(185, 11, 0, 'Consultation', '', '<p>Our Full Suite of Consulting Services</p>\r\n<p>Weâ€™re passionate about helping lab startups get off the ground efficiently and successfully. We provide a large array of services to simplify the process, giving you all the help you need, regardless of where you are in the process. Through our network, weâ€™ll be able to answer all your questions and get everything down to the last detail finalized so that your lab can run smoothly without setbacks. To learn more, browse through each of our available services below.</p>', '', '07e492c6eb2907630d10c1a871562b67.jpg', '', '2019-12-07 17:19:53', '2019-12-07 17:21:03', 1, '2019-12-07 00:00:00', 'blog', '', '', '', 0),
(186, 71, 0, 'Liofilchem® Giotto 2', '', '<p><strong>Automated reader of Liofilchem® Systems for identification and susceptibility testing</strong></p>\r\n<p>Convenient, Fast and Easy to Use</p>\r\n<p>Giotto 2 is an automated reader of Liofilchem’s Systems designed for microbial identification and susceptibility testing. The instrument uses color digital imaging for reading and interpreting the colorimetric reactions resulting on Liofilchem’s Systems after incubation. A personal computer integrated with the images capturing system allows a complete management of data along with electronic recording of results and HD photos. Customizable result reports are created in PDF format. The software is easy to update and equipped with remote assistance service via the internet.</p>\r\n<p>Liofilchem provides a wide range of Systems for screening, ID and AST intended for either clinical microbial laboratories or Industries. Giotto 2 can be used with all kind of Liofilchem’s Systems. Contact the manufacturer or the local representative for reading a System which is not configured with the instrument yet.</p>\r\n<p><strong>Benefit:</strong></p>\r\n<ul style=\"list-style-type: disc;\">\r\n<li>Automatic reading and interpretation of Liofilchem®</li>\r\n<li>ID and AST systems.</li>\r\n<li>Ideal for clinical and industrial microbiology lab.</li>\r\n<li>Color digital imaging technology.</li>\r\n<li>Electronic archive of test results and images.</li>\r\n<li>Automatic updates by built-in internet connection.</li>\r\n<li>Remote technical assistance.</li>\r\n<li>Compact format.</li>\r\n</ul>\r\n<p style=\"padding-left: 240px;\"><img src=\"/prolabios.com/content/photo/0e1f09c139b5101472d52bd892bf11e2.jpg\" alt=\"\" width=\"375\" height=\"212\" /></p>\r\n<p>Analysis in 3 quick steps:</p>\r\n<ol>\r\n<li>Select the Liofilchem® ID/AST system.</li>\r\n<li>Enter the sample data.</li>\r\n<li>Read. The user reviews and confirms, or can adjust any results.</li>\r\n</ol>\r\n<p> </p>\r\n<p style=\"padding-left: 120px;\"><img src=\"/prolabios.com/content/photo/10f4986ebcd776a9bbbdfa666eb154e5.jpg\" alt=\"\" width=\"571\" height=\"373\" /></p>\r\n<p>Save, print out and browse results</p>\r\n<ul style=\"list-style-type: circle;\">\r\n<li>Automatic save of images and results of performed analysis.</li>\r\n<li>Print out the test results or send by e-mail.</li>\r\n<li>Recall data by test code, patient name, microorganism or<br />other criteria.</li>\r\n</ul>\r\n<p> </p>\r\n<p><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p>kjjo</p>', '', '0862079724fdd0a312837dee1bc9b718.jpg', '', '2019-12-08 15:10:36', '2024-08-06 20:25:55', 1, '2024-08-06 00:00:00', 'blog', '', '', '', 0),
(187, 72, 0, 'BactoBank', '', '<p><strong>BactoBank</strong></p>\r\n<p><strong>The Pulse BactoBank</strong> is a system intended for the long-term storage of microorganisms at low temperature using ceramic beads.</p>\r\n<p>The maintenance of quality control or clinical cultures for long term storage is a routine practice by hospitals. They usually employ home-made preservation systems.&nbsp; However, the availability of commercial systems for the preservation of microorganisms has revolutionized this hospital practice and has reduced workload substantially.</p>\r\n<p>BactoBank contains a plastic vial with ceramic beads suspended in a cryogenic fluid. Upon inoculation into the cryogenic fluid, the microorganisms will adhere to the surface of the bead. In this manner, the microorganisms will maintain long term survival when the coated beads are stored at refrigerated temperatures.</p>\r\n<p>BactoBank is available in several colour beads to allow the laboratory to identify different categories of microorganisms.&nbsp; The compact vial size allows the storage of a large quantity of cultures using a minimum space<sup>2</sup>.&nbsp; Each individual bead can be removed from the vial without thawing the entire vial sample.&nbsp; The bead system permits the microorganism to be reactivated and be transferred onto a plated media or tube media for recovery. This method has been proven to be a simple, rapid, safe and reliable procedure to be routinely used to preserve quality control cultures or cultures for other applications for long term storage.</p>\r\n<p>Vials: Each vial contains ceramic beads suspended in a cryogenic fluid.</p>\r\n<p>Additional Items Required: Pure Culture to be preserved. Sterile loops. Sterile pipet tips. Sterile hooks or needles.&nbsp; Freezer at -20 degree C or below.&nbsp; Biohazard Waste Bag.</p>\r\n<p>Advantages:</p>\r\n<ul>\r\n<li>Stackable box</li>\r\n<li>Box with position indicated for better arrangement</li>\r\n<li>Plastic box good for freezing</li>\r\n<li>Multi color and single color available.</li>\r\n<li>Various kit sizes (25, 50, 100 vials)</li>\r\n<li>Long shelf life</li>\r\n<li>Color coded beads matched with color coded caps</li>\r\n<li>Leak proof cap and vial</li>\r\n</ul>\r\n<p>Maintains viability for a wide variety of Microorganisms, including (not limited to):<em> N. gonorrhoeae, H. influenzae, B. vulgatus, C. albicans, A. brasiliensis.</em></p>\r\n<p><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>', '', '5712808a78f88409f217027759b2883a.jpg', '', '2019-12-08 16:05:56', '2020-03-08 20:20:35', 1, '2020-03-08 00:00:00', 'blog', '', '', '', 0),
(188, 73, 0, 'Microbial Staining and Fixatives', '', '<p>Microbiology stains are used to detect and identify microorganisms that would otherwise be difficult to find in clinical specimens. Simple positively or negatively charged dyes create a fast discovery. The premixed solutions artificially color to help observe movement, structure, and characteristics of live or preserved specimens. Differentiating microorganisms based on properties, color combination procedures like the Gram stain or acid-fast techniques require microbiology stains.</p>\r\n<p style=\"text-align: justify;\">The following points highlight the top five types of Staining. The types are: 1. Simple Staining 2. Differential Staining 3. Gram Staining 4. Acid Fast Staining 5. Endospore Staining.</p>\r\n<p><strong>Staining&nbsp;Type # 1. Simple Staining:</strong></p>\r\n<p style=\"text-align: justify;\">Colouration of microorganisms by applying single dye to a fixed smear is termed simple staining. One covers the fixed smear with stain for specific period, after which this solution is washed off with water and slide blotted dry. Basic dyes like crystal violet, methylene blue and carbolfuchsin are frequently used in simple staining to determine the size, shape and arrangement of prokaryotic cells.</p>\r\n<p style=\"text-align: justify;\"><strong>Staining Type # 2. Differential Staining:</strong></p>\r\n<p style=\"text-align: justify;\">These staining procedures are used to distinguish organisms based on staining properties. They are slightly more elaborate than simple staining techniques that the cells may be exposed to more than one dye or stain, for instance use of Gram staining which divides bacteria into two classes-Gram negative and Gram positive.</p>\r\n<p style=\"text-align: justify;\"><strong>Staining Type # 3. Gram Staining:</strong></p>\r\n<p style=\"text-align: justify;\">It is one of the most important and widely used differential staining techniques in microbiology. This technique was introduced in 1884 by Danish Physician Christian Gram. In the first step the smear is stained with basic dye crystal violet (Primary stain) followed by treatment with iodine solution functioning as mordant. Iodine increases the interaction between cell &amp; dye so that cell stains strongly. The smear is next decolourized by washing with ethanol or acetone. This step generates the differential aspect of Gram stains. Gram positive bacteria retain crystal violet and become colourless. Finally smear is counter-stained with a simple basic dye different in color from Crystal violet. Safranin is the most common counter stain which colours Gram negative bacteria pink to red and leaves Gram positive bacteria dark purple. The differences in staining responses to the Gram stain can be related to chemical and physical difference of cell walls. The Gram-negative bacterial cell wall is thin, complex multilayered structure and contains relatively high lipid contents in addition to protein and mucopeptide. The higher amount of lipid is readily dissolved by alcohol, resulting information of large pore in the cell wall, thus facilitate leakage of crystal- violet &ndash; iodine (CV-I) complex which results in decolorization of the bacterial cell. Which later take counter stain and appears red. In contrast the cell wall of gram+ve bacteria is thick and chemically simple, composed mainly of mucopeptides. When treated with alcohol, it causes dehydration and closure of cell wall pore, thereby does not allow the loss of (CV-I) complex and cell remain purple.</p>\r\n<p style=\"text-align: justify;\"><strong>Staining Type # 4. Acid Fast Staining:</strong></p>\r\n<p style=\"text-align: justify;\">It is another important differential staining procedure. It is most commonly used to identify Mycobacterium spp. These bacteria have cell wall with high lipid content such as mycolic acid -a group of branched chain hydroxy lipids, which prevent dyes from readily binding to cells. They can be stained by Ziehl-Nulsen method, which uses heat and phenol to derive basic fuchsin into the cells. Mycrobacterium spp. were penetrated with basic fuchsin, not easily decolourized by acidified alcohol (acid alcohol) and thus are said to be acid fast. Non arid fast bacteria are decolourized by arid alcohol and thus are stained blue by methylene blue counter stain.</p>\r\n<p style=\"text-align: justify;\"><strong>Staining Type # 5. Endospore Staining:</strong></p>\r\n<p style=\"text-align: justify;\">Spore formation takes place in some bacterial genera to withstand unfavourable conditions. All bacteria cannot form spores, only few bacterial genera including Bacillus, Clostridium, Desulfotomaculum produce sporulating structure inside vegetative cells called endospore. Endospore morphology and location vary with species and are valuable for identification Endospores are not stained well by most dyes, but once stained, they strongly resist decolorization. In the Schaffer-Fulton procedure, endospores are first stained by heating bacteria with malachite green, which is very strong stain that can penetrate endospores. After malachite green treatment, the rest of the cell is washed free of dye with water and is counter-stained with safranin. This technique yields a green endospore with red vegetative cell.</p>\r\n<p style=\"text-align: justify;\"><strong>Product range for Microbial Staining and Fixatives:</strong></p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 175px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 31px;\">\r\n<td style=\"width: 15.3692%; text-align: center; height: 31px;\"><strong>Catalague</strong></td>\r\n<td style=\"width: 29.7405%; text-align: center; height: 31px;\"><strong>Product</strong></td>\r\n<td style=\"width: 54.8902%; text-align: center; height: 31px;\"><strong>Application</strong></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 15.3692%; height: 18px; text-align: center;\">80294</td>\r\n<td style=\"width: 29.7405%; height: 18px;\">ALBERT Color KIT</td>\r\n<td style=\"width: 54.8902%; height: 18px; text-align: justify;\">ALBERT COLOR KIT is a kit for staining diphtheria corynebacteria present in clinical samples or culture media. The stain reveals the granules of volutin present in <em>Corynebacterium</em> <em>diphtheriae</em> and other species of the genus <em>Corynebacterium.</em></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 15.3692%; height: 18px; text-align: center;\">80293</td>\r\n<td style=\"width: 29.7405%; height: 18px;\">GRAM Color KIT</td>\r\n<td style=\"width: 54.8902%; height: 18px; text-align: justify;\">GRAM COLOR KIT is a kit for staining micro-organisms that allows them to be differentiated into two categories: Gram-positives (Gram+), which are coloured blue, and Gram-negatives (Gram-), which are coloured red. Combined with direct observation of the cell morphology, this staining constitutes the first level in the taxonomic classification of prokaryotes.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 15.3692%; height: 18px; text-align: center;\">80380</td>\r\n<td style=\"width: 29.7405%; height: 18px;\">KINYOUN Color KIT</td>\r\n<td style=\"width: 54.8902%; height: 18px; text-align: justify;\">KINYOUN COLOR KIT (Tan-Thiam-Hok and Devulder method) is a kit for colouring alcohol acid resistant bacteria in clinical samples or culture media. The Kinyoun colouring (Tan-Thiam-Hok and Devulder method) is an alternative to colouring alcohol3acid resistant bacteria that is simpler to administer than hot Ziehl Neelsen colouring. Colouring can be carried out using the following methods: Tan-Tiam-Hok, Devulder (hot version), Devulder (cold version).</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 15.3692%; height: 18px; text-align: center;\">80276</td>\r\n<td style=\"width: 29.7405%; height: 18px;\">ZIEHL &ndash; NEELSEN Color KIT</td>\r\n<td style=\"width: 54.8902%; height: 18px; text-align: justify;\">ZIEHL NEELSEN KIT is a kit for colouring acid-alcohol resistant bacteria present in pathological samples or in culture media. This colouring is particularly useful is performing a microscope examination for the presence of mycobacteria.</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 15.3692%; height: 18px; text-align: center;\">87008</td>\r\n<td style=\"width: 29.7405%; height: 18px;\">Lactophenol Cotton Blue Droppers</td>\r\n<td style=\"width: 54.8902%; height: 18px; text-align: justify;\">Lactophenol Cotton Blue Droppers is a mounting medium and a staining agent used in the preparation of slides for microscopic examination of fungi from clinical specimens, food and environmental samples.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>\r\n<p>&nbsp;</p>', '', '3c019ba2327100641e41a501f61bbfc4.jpg', '', '2019-12-08 21:11:45', '2020-03-08 20:21:37', 1, '2020-03-08 00:00:00', 'blog', '', '', '', 0),
(191, 75, 0, 'Reference Standards', '', '<p>Reference Standards : A reference standard is a substance prepared for use as the standard in an assay, identification, or purity test and should have a quality appropriate for its use.</p>\r\n<p>From: Developing Solid Oral Dosage Forms (Second Edition), 2017</p>', '', 'ff61572e3fdadbeeeecf606defa64ff1.jpg', '', '2020-02-24 19:21:39', '2020-02-24 20:07:15', 1, '2020-02-24 00:00:00', 'blog', '', '', '', 0),
(201, 78, 0, 'Food and Beverages Standards', '', '<p>We understand that when it comes to determining food\'s nutritional value, safety and quality matters. We proudly offer comprehensive range of high-quality products and reliable testing solutions in helping you to deliver accurate results in order to keep food safe along with meeting the regulatory requirements.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>', '', '5ec345f0ede6671aaacf487242d621e3.jpg', '', '2020-02-24 19:59:16', '2020-03-08 20:48:54', 1, '2020-03-08 00:00:00', 'blog', '', '', '', 0),
(193, 80, 0, 'Environmental Standards', '', '<p>We proudly announce our support for the environment industries with reference standards of soil, air, climate, water, wastewater and effluents to help them ensure that your results are reliable and fit for purpose.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>', '', '5343ce39b2e9e711343af7b7cd53735f.jpg', '', '2020-02-24 19:31:22', '2020-03-08 20:48:43', 1, '2020-03-08 00:00:00', 'blog', '', '', '', 0),
(195, 77, 0, 'Green Standards', '', '<p>We are specialized manufacturer of PHYTOCHEMICALS. We leverage extensive experience of our phytochemists in the field of plant raw materials, profound knowledge of phytochemistry and innovative approach to scientific tasks, state of art facility and instruments for isolating bioactive Phytochemicals from different medicinal plants makes.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>', '', '17263263b4978cb87cfeb49c72c2985e.jpg', '', '2020-02-24 19:34:26', '2020-03-08 20:49:12', 1, '2020-03-08 00:00:00', 'blog', '', '', '', 0),
(200, 79, 0, 'Agro-Chemical Standards', '', '<p>We offer a comprehensive range of these standards which includes Fertilizers, Pesticides, Insecticides, Herbicides and Bactericides. Specialized testing products are available to cater the needs of agricultural products analysts.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>', '', '7f13b1674491319ff2c388a85d7a06b3.jpg', '', '2020-02-24 19:38:19', '2020-03-08 20:49:03', 1, '2020-03-08 00:00:00', 'blog', '', '', '', 0),
(212, 4, 1, 'Official Announcement! Lab Indonesia 2020 Rescheduled to 1 - 3 September 2021', '', '<p>Greetings from Lab Indonesia!</p>\r\n<p>This November 25 â€“ 27, 2020 would have been the date for Lab Indonesia 2020, however due to the still increasing number of cases worldwide and the travel uncertainty, our management has made the decision to postpone Lab Indonesia 2020 scheduled for 25 â€“ 27 November 2020 at JIExpo Kemayoran to <strong>1 â€“ 3 September 2021</strong> at the same venue. Â We sincerely apologize for any inconvenience this may caused and appreciate your understanding and support. Kindly find attached official letter of 2<sup>nd</sup> postponement Lab Indonesia 2020 for your references.</p>\r\n<p>Another issue we would like to discuss with you is Lab Indonesia event schedule. Regularly Lab Indonesia is held bi-annually but due to pandemic Covid-19, the implementation of Lab Indonesia has changed, Lab Indonesia 2020 moved to 2021. The next edition of Lab Indonesia planned whether in April or September 2022 ? <strong><em>When do you think the best month for the next edition? Kindly indicate your most preferred time.</em></strong></p>\r\n<p>In this unprecedented time for us around the world and we realize that even though many are facing challenges, we have to keep moving forward. With your input and with our effort, together we will make this event to be successful. Â Thank you and should you have any questions, please do not hesitate to contact us.</p>\r\n<p>Stay safe and healthy!</p>\r\n<p>Â </p>\r\n<p><em>Best Regards,</em></p>\r\n<p><strong>Dewi Â </strong></p>\r\n<p>Lab Indonesiaâ”‚Cosmobeaute Indonesia</p>', '', '83ff89beec840b63367d3d6fbcb62eb7.jpg', '', '2020-03-17 14:58:00', '2020-09-22 17:29:22', 3, '2020-03-10 00:00:00', 'blog', '', '', '', 0),
(210, 76, 0, 'Pharmaceutical Reference Standards', '', '<div class=\"post-body text-justify m-t-10\">\r\n<p>A pharmaceutical reference standard is a highly characterized material suitable to test the identity, strength, quality and purity of substances for pharmaceutical use and medicinal products.</p>\r\n<p>Types of Reference Standards in Pharmaceutical Parlance:</p>\r\n<ol>\r\n<li>Primary Reference Standards</li>\r\n<li>Pharmacopeial Reference Standards</li>\r\n<li>Secondary Reference Standards</li>\r\n<li>Impurity Reference Standards</li>\r\n</ol>\r\n<p>&nbsp;</p>\r\n<p><strong>For inquiry please kindly email to : lisa@prolabios.com</strong></p>\r\n</div>', '', '31de63912a8148f55abbe148f45a6010.jpg', '', '2020-02-24 20:05:29', '2020-03-08 20:48:36', 1, '2020-03-08 00:00:00', 'blog', '', '', '', 0),
(214, 81, 0, 'Thermometer', '', '<p style=\"text-align: justify;\">A&nbsp;<strong>thermometer&nbsp;</strong>is a device that&nbsp;measures temperature&nbsp;or a&nbsp;temperature gradient&nbsp;(the degree of hotness or coldness of an object) A thermometer has two important elements: (1) a temperature sensor (e.g. the bulb of a&nbsp;mercury-in-glass thermometer&nbsp;or the pyrometric sensor in an&nbsp;infrared thermometer) in which some change occurs with a change in temperature; and (2) some means of converting this change into a numerical value (e.g. the visible scale that is marked on a mercury-in-glass thermometer or the digital readout on an infrared model). Thermometers are widely used in technology and industry to monitor processes, in&nbsp;meteorology, in medicine, and in scientific research. During the&nbsp;<strong>COVID-19 pandemic</strong>&nbsp;they were used by businesses to detect the fever brought on by the virus.</p>\r\n<p style=\"text-align: justify;\">Some of the principles of the thermometer were known to Greek philosophers of two thousand years ago. The Italian physician&nbsp;Santorio Santorio&nbsp;(Sanctorius, 1561-1636)&nbsp;is commonly credited with the invention of the first thermometer, but its standardisation was completed through the 17th and 18th centuries.</p>\r\n<p style=\"text-align: justify;\">There are many types of thermometers used under Science, Geography etc.</p>', '', '3e057c47038ba40163ddc17e13a693e0.jpg', '', '2020-06-16 22:27:11', '0000-00-00 00:00:00', 1, '2020-06-16 00:00:00', 'blog', '', '', '', 0),
(215, 4, 0, 'Seminar LabIndonesia Digital Event 2020 - Pengujian Endotoxin Bakteri Menurut Farmakope', '', '<p>Untuk pemahaman lebih dalam atau juga refresh training mengenai pengujian <strong>Bacterial Endotoxin sesuai standard USP chapter &lt;85&gt;</strong>, jangan lupa untuk menghadiri Seminar sesi kami pada tanggal 25 November 2020 di jam <strong>14:50 &ndash; 15:35 WIB</strong>, room 2 yang akan menampilkan narasumber <strong>Prof.apt. Marlia Singgih, PhD.</strong> dosen Mikrobiologi Farmasi di Institut Teknologi Bandung.</p>', '', '228708acaa423fd51b578870923a7d0e.jpg', '', '2020-11-24 13:07:01', '2020-11-24 13:08:58', 1, '2020-11-24 00:00:00', 'blog', '', '', '', 0);

